  # icon("users", class: "size-5 text-gray-400")
  def icon(name, **options)
    path = ICONS.fetch(name.to_s)
    options[:class] = [ "size-5 shrink-0", options[:class] ].compact.join(" ")

    tag.svg(**options, xmlns: "http://www.w3.org/2000/svg", fill: "none", viewBox: "0 0 24 24",
            "stroke-width": 1.5, stroke: "currentColor", "aria-hidden": true) do
      tag.path("stroke-linecap": "round", "stroke-linejoin": "round", d: path)
    end
  end

  # "Lucía Fernández" -> "LF"
  def initials(name)
    name.to_s.split.first(2).map { |word| word[0] }.join.upcase
  end
end
